SELECT FROM tianquan_oauth.oauth_security_state WHERE tenant_id = #{tenantId} AND deleted_at IS NULL AND id IN
#{id}
ORDER BY id ASC

mapper.update:
UPDATE tianquan_oauth.oauth_security_state s
SET version = s.version + 1, update_user_id = #{actor}, update_time = #{now}
WHERE s.tenant_id = #{tenantId} AND s.id = #{id} AND s.version = #{expectedVersion}
  AND s.target_type = 'REALM' AND s.target_key = 'self' AND s.deleted_at IS NULL
  AND NOT EXISTS (
      SELECT 1 FROM tianquan_oauth.oauth_token t
      WHERE t.tenant_id = #{tenantId} AND t.token_digest = #{tokenDigest} AND t.deleted_at IS NULL
  )

UPDATE tianquan_oauth.oauth_security_state s
SET revision = #{revision}, version = s.version + 1, update_user_id = #{actor}, update_time = #{now}
WHERE s.tenant_id = #{tenantId} AND s.id = #{id} AND s.version = #{expectedVersion}
  AND s.target_type = 'REALM' AND s.target_key = 'self' AND s.deleted_at IS NULL
  AND s.revision < #{revision}
  AND NOT EXISTS (
      SELECT 1 FROM tianquan_oauth.oauth_revocation r
      WHERE r.tenant_id = #{tenantId} AND r.target_type = #{targetType}
        AND r.target_key = #{targetKey} AND r.deleted_at IS NULL
  )

UPDATE tianquan_oauth.oauth_security_state s
SET revision = #{revision}, version = s.version + 1, update_user_id = #{actor}, update_time = #{now}
WHERE s.tenant_id = #{tenantId} AND s.id = #{id} AND s.version = #{expectedVersion}
  AND s.target_type = 'REALM' AND s.target_key = 'self' AND s.deleted_at IS NULL
  AND s.revision < #{revision}
  AND NOT EXISTS (SELECT 1 FROM tianquan_oauth.oauth_security_state subject_state
      WHERE subject_state.tenant_id = #{tenantId} AND subject_state.target_type = 'SUBJECT'
        AND subject_state.target_key = #{subject} AND subject_state.deleted_at IS NULL)
  AND NOT EXISTS (SELECT 1 FROM tianquan_oauth.oauth_authorization a
      WHERE a.tenant_id = #{tenantId} AND a.principal_name = #{subject}
        AND a.principal_type = 'USER' AND a.deleted_at IS NULL)
  AND NOT EXISTS (SELECT 1 FROM tianquan_oauth.oauth_authentication auth
      WHERE auth.tenant_id = #{tenantId} AND auth.subject = #{subject} AND auth.deleted_at IS NULL)

UPDATE tianquan_oauth.oauth_security_state
SET version = version + 1, update_user_id = #{actor}, update_time = #{now}
WHERE tenant_id = #{tenantId} AND id = #{id} AND version = #{expectedVersion}
  AND target_type = 'SUBJECT' AND target_key = #{subject}
  AND (directory_subject_revision > #{sourceRevision}
       OR (directory_subject_revision = #{sourceRevision} AND directory_subject_fingerprint = #{fingerprint}))
  AND deleted_at IS NULL

UPDATE tianquan_oauth.oauth_security_state s
SET version = s.version + 1, update_user_id = #{actor}, update_time = #{now}
WHERE s.tenant_id = #{tenantId} AND s.id = #{id} AND s.version = #{expectedVersion}
  AND s.target_type = 'REALM' AND s.target_key = 'self' AND s.deleted_at IS NULL
  AND NOT EXISTS (SELECT 1 FROM tianquan_oauth.oauth_consent c
                  WHERE c.tenant_id = #{tenantId} AND c.client_pk = #{clientPk}
                    AND c.subject = #{subject} AND c.status = 'ACTIVE' AND c.deleted_at IS NULL)

UPDATE tianquan_oauth.oauth_security_state s
SET version = s.version + 1, update_user_id = #{actor}, update_time = #{now}
WHERE s.tenant_id = #{tenantId} AND s.id = #{id} AND s.version = #{expectedVersion}
  AND s.target_type = 'REALM' AND s.target_key = 'self' AND s.deleted_at IS NULL
  AND NOT EXISTS (SELECT 1 FROM tianquan_oauth.oauth_authorization a
                  WHERE a.tenant_id = #{tenantId} AND a.id = #{authorizationId} AND a.deleted_at IS NULL)

UPDATE tianquan_oauth.oauth_security_state s
SET version = s.version + 1, update_user_id = #{actor}, update_time = #{now}
WHERE s.tenant_id = #{tenantId} AND s.id = #{id} AND s.version = #{expectedVersion}
  AND s.target_type = 'REALM' AND s.target_key = 'self' AND s.deleted_at IS NULL
  AND NOT EXISTS (SELECT 1 FROM tianquan_oauth.oauth_token t
                  WHERE t.tenant_id = #{tenantId} AND t.authorization_pk = #{authorizationId}
                    AND t.consumed_at IS NULL AND t.revoked_at IS NULL AND t.deleted_at IS NULL)

UPDATE tianquan_oauth.oauth_security_state s
SET version = s.version + 1, update_user_id = #{actor}, update_time = #{now}
WHERE s.tenant_id = #{tenantId} AND s.id = #{id} AND s.version = #{expectedVersion}
  AND s.target_type = 'SUBJECT' AND s.target_key = #{subject} AND s.deleted_at IS NULL
  AND s.directory_subject_ordered_revision >= #{sourceRevision}

  AND EXISTS (SELECT 1 FROM tianquan_oauth.oauth_subject_delivery_receipt receipt
              WHERE receipt.tenant_id = #{tenantId} AND receipt.identity_sub = #{subject}
                AND receipt.source_revision = #{previousRevision} AND receipt.deleted_at IS NULL)

UPDATE tianquan_oauth.oauth_security_state s
SET version = s.version + 1, update_user_id = #{actor}, update_time = #{now}
WHERE s.tenant_id = #{tenantId} AND s.id = #{id} AND s.version = #{expectedVersion}
  AND s.target_type = 'SUBJECT' AND s.target_key = #{subject} AND s.deleted_at IS NULL
  AND s.directory_subject_ordered_revision >= #{sourceRevision}
  AND EXISTS (SELECT 1 FROM tianquan_oauth.oauth_subject_delivery_receipt receipt
              WHERE receipt.tenant_id = #{tenantId} AND receipt.identity_sub = #{subject}
                AND receipt.source_revision = #{sourceRevision} AND receipt.event_id = #{eventId}
                AND receipt.previous_revision = #{previousRevision} AND receipt.payload_fingerprint = #{payloadFingerprint}
                AND receipt.deleted_at IS NULL)

UPDATE tianquan_oauth.oauth_security_state
SET deleted_at = CURRENT_TIMESTAMP AT TIME ZONE 'UTC', version = version + 1,
    update_user_id = #{po.updateUserId}, update_time = #{po.updateTime}
WHERE tenant_id = #{tenantId} AND id = #{po.id}
  AND version = #{expectedVersion} AND deleted_at IS NULL
